//! The GDAL-verified EPSG allow-list of the standard build (issue #337).
//!
//! `epsg_allowlist.tsv.gz` is generated by `scripts/crs-allowlist/generate.py` from a
//! grid-free, offline GDAL/PROJ. Each row maps an EPSG code to an explicit PROJ or WKT1
//! definition (a `towgs84` Helmert or null shift, never a grid) and to the EPSG
//! transformation it reproduces, with EPSG's stated accuracy. A code is listed only when
//! that definition, run through this crate's resolver and proj4rs, landed within 1 mm in
//! ECEF of GDAL's only-best, no-ballpark result at all 18 samples of its area of use.
//! Codes GDAL refuses offline, or that need grids, epochs or unverified methods, are absent.
use serde::Serialize;
use std::{io::Read, sync::OnceLock};

pub(crate) const TABLE: &[u8] = include_bytes!("epsg_allowlist.tsv.gz");
const FORMAT: &str = "# rusty-tiles EPSG allow-list, format 1";

/// What a listed definition reproduces.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum OperationKind {
    /// Same datum as WGS 84: a map projection conversion, no datum transformation.
    Conversion,
    /// A datum transformation EPSG defines with zero parameters. Not exact: EPSG states
    /// its accuracy (for example GDA2020 to WGS 84 (2), 3 m).
    Null,
    /// A 3- or 7-parameter Helmert datum transformation.
    Helmert,
}

#[derive(Debug, PartialEq)]
pub(crate) struct Entry {
    pub(crate) code: u32,
    /// EPSG's stated accuracy in metres; `None` when EPSG states none.
    pub(crate) accuracy_metres: Option<f64>,
    pub(crate) kind: OperationKind,
    /// EPSG identifier(s) and name(s) of the datum transformation; empty for a conversion.
    pub(crate) operation_id: String,
    pub(crate) operation: String,
    pub(crate) definition: String,
}

#[derive(Debug, PartialEq)]
pub(crate) struct Table {
    pub(crate) epsg: String,
    pub(crate) proj: String,
    pub(crate) gdal: String,
    /// Codes the resolver's built-in WGS 84 cases cover; they are not rows.
    pub(crate) builtin: usize,
    pub(crate) entries: Vec<Entry>,
}

impl Table {
    pub(crate) fn get(&self, code: u32) -> Option<&Entry> {
        self.entries
            .binary_search_by_key(&code, |entry| entry.code)
            .ok()
            .map(|index| &self.entries[index])
    }

    /// "EPSG v13.102, PROJ 9.9.0, GDAL 3.13.3"
    pub(crate) fn versions(&self) -> String {
        format!("EPSG {}, PROJ {}, GDAL {}", self.epsg, self.proj, self.gdal)
    }
}

/// The embedded table, decompressed and parsed once per process.
pub(crate) fn table() -> &'static Table {
    static TABLE_CELL: OnceLock<Table> = OnceLock::new();
    TABLE_CELL.get_or_init(|| {
        let mut text = String::new();
        flate2::read::GzDecoder::new(TABLE)
            .read_to_string(&mut text)
            .expect("embedded EPSG allow-list is valid gzip UTF-8");
        // Unit tests parse the committed table; a failure here is a build defect.
        parse(&text).expect("embedded EPSG allow-list parses")
    })
}

/// Parse the generator's text format: `#` header lines, then sorted tab-separated rows of
/// code, accuracy (metres or `unknown`), kind, operation id, operation name and definition.
pub(crate) fn parse(text: &str) -> Result<Table, String> {
    let mut lines = text.lines();
    if lines.next() != Some(FORMAT) {
        return Err("not a format 1 EPSG allow-list".into());
    }
    let versions = lines
        .next()
        .and_then(|line| line.strip_prefix("# "))
        .ok_or("missing version line")?;
    let field = |name: &str| {
        versions
            .split_whitespace()
            .find_map(|item| item.strip_prefix(name)?.strip_prefix('='))
            .filter(|value| !value.is_empty())
            .map(str::to_owned)
            .ok_or_else(|| format!("version line lacks {name}"))
    };
    let (epsg, proj, gdal) = (field("epsg")?, field("proj")?, field("gdal")?);
    let mut counts = None;
    let mut entries: Vec<Entry> = Vec::new();
    for (number, line) in lines.enumerate() {
        if let Some(comment) = line.strip_prefix('#') {
            if let Some(rest) = comment.trim().strip_prefix("codes=") {
                let (codes, builtin) =
                    rest.split_once(" builtin=").ok_or("malformed count line")?;
                counts = Some((
                    codes.parse::<usize>().map_err(|e| e.to_string())?,
                    builtin.parse::<usize>().map_err(|e| e.to_string())?,
                ));
            }
            continue;
        }
        let row = || format!("row {}", number + 3);
        let fields: Vec<&str> = line.split('\t').collect();
        let [code, accuracy, kind, operation_id, operation, definition] = fields[..] else {
            return Err(format!("{}: expected 6 tab-separated fields", row()));
        };
        let code = code
            .parse::<u32>()
            .map_err(|_| format!("{}: invalid code", row()))?;
        let accuracy_metres = match accuracy {
            "unknown" => None,
            value => Some(
                value
                    .parse::<f64>()
                    .ok()
                    .filter(|v| v.is_finite() && *v >= 0.)
                    .ok_or_else(|| format!("{}: invalid accuracy", row()))?,
            ),
        };
        let kind = match kind {
            "conversion" => OperationKind::Conversion,
            "null" => OperationKind::Null,
            "helmert" => OperationKind::Helmert,
            _ => return Err(format!("{}: unknown kind {kind}", row())),
        };
        if (kind == OperationKind::Conversion) != operation.is_empty() || definition.is_empty() {
            return Err(format!("{}: operation does not match its kind", row()));
        }
        if entries.last().is_some_and(|last| last.code >= code) {
            return Err(format!("{}: codes must be strictly increasing", row()));
        }
        entries.push(Entry {
            code,
            accuracy_metres,
            kind,
            operation_id: operation_id.to_owned(),
            operation: operation.to_owned(),
            definition: definition.to_owned(),
        });
    }
    let (codes, builtin) = counts.ok_or("missing count line")?;
    if codes != entries.len() {
        return Err(format!(
            "count line states {codes} codes, table has {}",
            entries.len()
        ));
    }
    Ok(Table {
        epsg,
        proj,
        gdal,
        builtin,
        entries,
    })
}

/// The datum operation an allow-listed EPSG code resolved to, stated in reports.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CrsOperation {
    /// `EPSG:<code>` as resolved.
    pub source: String,
    pub kind: OperationKind,
    /// EPSG name of the datum transformation, or `none` for a same-datum conversion.
    pub operation: String,
    /// EPSG identifier of the datum transformation (for example `EPSG:8450`).
    pub operation_id: Option<String>,
    /// EPSG's stated accuracy of the transformation in metres, `None` when EPSG states
    /// none. A null transformation keeps its stated accuracy: it is not exact.
    pub accuracy_metres: Option<f64>,
    /// How the definition was verified, with the GDAL/PROJ/EPSG versions.
    pub verification: String,
}

impl CrsOperation {
    pub(crate) fn new(entry: &Entry, table: &Table) -> Self {
        let conversion = entry.kind == OperationKind::Conversion;
        Self {
            source: format!("EPSG:{}", entry.code),
            kind: entry.kind,
            operation: if conversion {
                "none (same datum as WGS 84)".into()
            } else {
                entry.operation.clone()
            },
            operation_id: (!entry.operation_id.is_empty()).then(|| entry.operation_id.clone()),
            accuracy_metres: entry.accuracy_metres,
            verification: format!(
                "GDAL-verified allow-list ({}): 18 sampled points within 1 mm of GDAL's best operation",
                table.versions()
            ),
        }
    }

    /// One-line summary for human-readable reports.
    pub fn summary(&self) -> String {
        let accuracy = match (self.kind, self.accuracy_metres) {
            (OperationKind::Conversion, _) => "no datum change".to_owned(),
            (_, Some(metres)) => format!("EPSG-stated accuracy {metres} m"),
            (_, None) => "EPSG states no accuracy".to_owned(),
        };
        let id = self
            .operation_id
            .as_deref()
            .map(|id| format!(" ({id})"))
            .unwrap_or_default();
        format!("{}: {}{id}, {accuracy}", self.source, self.operation)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "# rusty-tiles EPSG allow-list, format 1\n# epsg=v1 proj=9.9.0 gdal=3.13.3\n# criterion: invented\n# codes=2 builtin=1\n# code\taccuracy_m\tkind\toperation_id\toperation\tdefinition\n3031\tunknown\tconversion\t\t\t+proj=stere +lat_0=-90 +lat_ts=-71 +ellps=WGS84 +towgs84=0,0,0,0,0,0,0 +units=m +no_defs\n7844\t3.0\tnull\tEPSG:8450\tGDA2020 to WGS 84 (2)\t+proj=longlat +ellps=GRS80 +towgs84=0,0,0,0,0,0,0 +no_defs\n";

    #[test]
    fn parses_header_rows_and_lookups() {
        let table = parse(SAMPLE).unwrap();
        assert_eq!(
            (
                table.epsg.as_str(),
                table.proj.as_str(),
                table.gdal.as_str()
            ),
            ("v1", "9.9.0", "3.13.3")
        );
        assert_eq!(table.builtin, 1);
        let entry = table.get(7844).unwrap();
        assert_eq!(entry.kind, OperationKind::Null);
        assert_eq!(entry.accuracy_metres, Some(3.));
        assert_eq!(entry.operation, "GDA2020 to WGS 84 (2)");
        assert_eq!(table.get(3031).unwrap().accuracy_metres, None);
        assert!(table.get(3032).is_none() && table.get(0).is_none());
        let report = CrsOperation::new(entry, &table);
        assert_eq!(
            report.summary(),
            "EPSG:7844: GDA2020 to WGS 84 (2) (EPSG:8450), EPSG-stated accuracy 3 m"
        );
        let conversion = CrsOperation::new(table.get(3031).unwrap(), &table);
        assert_eq!(conversion.operation_id, None);
        assert!(conversion.summary().ends_with("no datum change"));
    }

    #[test]
    fn malformed_tables_are_rejected() {
        let row = SAMPLE.lines().nth(6).unwrap();
        for (broken, reason) in [
            (SAMPLE.replacen("format 1", "format 2", 1), "format"),
            (SAMPLE.replacen("gdal=3.13.3", "", 1), "version"),
            (SAMPLE.replacen("codes=2", "codes=3", 1), "count"),
            (
                SAMPLE.replacen("# codes=2 builtin=1\n", "", 1),
                "missing count",
            ),
            (SAMPLE.replacen("\t3.0\t", "\t-1\t", 1), "negative accuracy"),
            (SAMPLE.replacen("\t3.0\t", "\tNaN\t", 1), "NaN accuracy"),
            (SAMPLE.replacen("\tnull\t", "\tgrid\t", 1), "kind"),
            (
                SAMPLE.replacen("GDA2020 to WGS 84 (2)", "", 1),
                "empty operation",
            ),
            (format!("{SAMPLE}{row}\n"), "duplicate"),
            (
                SAMPLE.replacen("\t+proj=longlat", "+proj=longlat", 1),
                "fields",
            ),
            (SAMPLE.replacen("7844\t", "x\t", 1), "code"),
        ] {
            assert!(parse(&broken).is_err(), "{reason}");
        }
    }

    #[test]
    fn embedded_table_is_sorted_versioned_and_grid_free() {
        let table = table();
        assert!(table.entries.len() > 3000, "{}", table.entries.len());
        assert!(table.versions().starts_with("EPSG v"));
        for entry in &table.entries {
            let definition = &entry.definition;
            assert!(
                definition.contains("towgs84") || definition.contains("TOWGS84"),
                "EPSG:{} {definition}",
                entry.code
            );
            for refused in ["grids", "geoidgrids", "@", "+init", "+t_epoch", "EPOCH["] {
                assert!(
                    !definition.contains(refused),
                    "EPSG:{} {definition}",
                    entry.code
                );
            }
            // The built-in WGS 84 cases are not repeated in the table.
            assert!(
                super::super::builtin_epsg(entry.code).is_none(),
                "EPSG:{}",
                entry.code
            );
        }
    }
}

/// End-to-end behaviour of `EPSG:<code>` through the shared resolver.
#[cfg(test)]
mod resolution {
    use super::super::PureTransform;
    use super::table;
    use crate::Error;

    /// GDAL-computed ECEF (committed by the generator) for MGA, NZTM, ETRS89, GDA94/GDA2020
    /// geographic and WGS 84 UTM samples. A native build answers with PROJ instead.
    #[test]
    #[cfg(not(feature = "native-geospatial"))]
    fn listed_codes_match_gdal_reference_ecef_within_a_millimetre() {
        use super::super::Transform;
        use super::OperationKind;
        use serde_json::Value;
        const REFERENCE: &str = include_str!("../../tests/fixtures/crs_allowlist_reference.json");
        let reference: Value = serde_json::from_str(REFERENCE).unwrap();
        let table = table();
        assert_eq!(reference["epsg"], table.epsg.as_str());
        assert_eq!(reference["proj"], table.proj.as_str());
        assert_eq!(reference["gdal"], table.gdal.as_str());
        let samples = reference["samples"].as_array().unwrap();
        let mut codes = std::collections::BTreeSet::new();
        for sample in samples {
            let code = sample["code"].as_u64().unwrap();
            codes.insert(code);
            let source: [f64; 3] = serde_json::from_value(sample["source"].clone()).unwrap();
            let ecef: [f64; 3] = serde_json::from_value(sample["ecef"].clone()).unwrap();
            let mut transform = Transform::new(&format!("EPSG:{code}"), 0.).unwrap();
            assert!(matches!(transform, Transform::Pure(_)), "EPSG:{code}");
            let got = transform.transform(&[source]).unwrap()[0];
            let error = (0..3)
                .map(|i| (got[i] - ecef[i]).powi(2))
                .sum::<f64>()
                .sqrt();
            assert!(error <= 0.001, "EPSG:{code} {source:?}: {error} m");
            let operation = transform.operation();
            if code == 32756 {
                assert!(
                    operation.is_none(),
                    "built-in WGS 84 UTM names no operation"
                );
                continue;
            }
            let operation = operation.unwrap_or_else(|| panic!("EPSG:{code} names its operation"));
            assert_eq!(operation.source, format!("EPSG:{code}"));
            assert_ne!(operation.kind, OperationKind::Conversion, "EPSG:{code}");
            // EPSG states an accuracy for each of these; a null shift is never exact.
            assert!(
                operation.accuracy_metres.is_some_and(|metres| metres > 0.),
                "EPSG:{code} {operation:?}"
            );
        }
        assert_eq!(
            codes.into_iter().collect::<Vec<_>>(),
            [2193, 4283, 7844, 7856, 25832, 28356, 32756]
        );
        let gda2020 = table.get(7844).unwrap();
        assert_eq!(
            (
                gda2020.kind,
                gda2020.accuracy_metres,
                gda2020.operation.as_str()
            ),
            (OperationKind::Null, Some(3.), "GDA2020 to WGS 84 (2)")
        );
        assert_eq!(table.get(4283).unwrap().kind, OperationKind::Helmert);
    }

    #[test]
    fn grids_epochs_and_unlisted_codes_stay_refused() {
        for definition in [
            "EPSG:27700",     // OSGB36 / British National Grid: OSTN15 grid
            "EPSG:4267",      // NAD27: grid
            "EPSG:26910",     // original NAD83 / UTM 10N: grid
            "EPSG:4490",      // CGCS2000: no non-ballpark operation offline
            "EPSG:3035",      // ETRS89 LAEA: outside the portable methods
            "EPSG:9000",      // ITRF2014: dynamic datum, needs a coordinate epoch
            "EPSG:32250",     // WGS 72 / UTM 50N: dynamic datum
            "EPSG:9057",      // WGS 84 (G1762): dynamic datum
            "EPSG:7856@2020", // coordinate epoch
            "EPSG:7844@2020.5",
            "EPSG:7856+5711", // compound with a vertical CRS
        ] {
            let error = PureTransform::new(definition, 0.).err().unwrap();
            assert!(
                matches!(error, Error::Environment(_)),
                "{definition}: {error}"
            );
            let message = error.to_string();
            assert!(
                message.starts_with("pure-Rust CRS transform unavailable: ")
                    && message.contains("--features native-geospatial"),
                "{definition}: {message}"
            );
            let code: u32 = definition[5..]
                .split(['@', '+'])
                .next()
                .unwrap()
                .parse()
                .unwrap();
            if !definition.contains(['@', '+']) {
                assert!(
                    table().get(code).is_none(),
                    "{definition} must not be listed"
                );
                assert!(
                    message.contains("GDAL-verified EPSG allow-list"),
                    "{message}"
                );
            }
        }
        assert!(matches!(
            PureTransform::new("EPSG:4979", 0.),
            Err(Error::Data(_))
        ));
    }
}

/// The engine half of the generator: evaluates candidate definitions with this resolver.
/// Run by `scripts/crs-allowlist/generate.py`; it reads and writes the files named by
/// `RUSTY_TILES_CRS_ALLOWLIST_CASES` and `RUSTY_TILES_CRS_ALLOWLIST_RESULTS`.
#[cfg(test)]
mod generator {
    use super::super::{builtin_epsg, PureTransform};
    use serde_json::{json, Value};

    #[test]
    #[ignore = "run by scripts/crs-allowlist/generate.py"]
    fn engine_results() {
        let input = std::env::var("RUSTY_TILES_CRS_ALLOWLIST_CASES").expect("cases path");
        let output = std::env::var("RUSTY_TILES_CRS_ALLOWLIST_RESULTS").expect("results path");
        let cases: Vec<Value> =
            serde_json::from_slice(&std::fs::read(input).unwrap()).expect("cases JSON");
        let mut results = Vec::with_capacity(cases.len());
        for case in &cases {
            let code = case["code"].as_u64().unwrap() as u32;
            let points: Vec<[f64; 3]> = serde_json::from_value(case["points"].clone()).unwrap();
            let outcomes: Vec<Value> = case["definitions"]
                .as_array()
                .unwrap()
                .iter()
                .map(|candidate| {
                    let definition = candidate["definition"].as_str().unwrap();
                    // EPSG input tests only the built-in cases, never this table.
                    let resolved = if candidate["form"] == "epsg" {
                        builtin_epsg(code)
                            .ok_or_else(|| "not a built-in code".to_owned())
                            .and_then(|_| {
                                PureTransform::new(definition, 0.).map_err(|e| e.to_string())
                            })
                    } else {
                        PureTransform::new(definition, 0.).map_err(|e| e.to_string())
                    };
                    match resolved {
                        Ok(operation) => {
                            let ok: Vec<Option<[f64; 3]>> = points
                                .iter()
                                .map(|point| operation.transform(&[*point]).ok().map(|v| v[0]))
                                .collect();
                            json!({"ok": ok})
                        }
                        Err(error) => json!({"ok": [], "error": error}),
                    }
                })
                .collect();
            results.push(json!({"code": code, "results": outcomes}));
        }
        std::fs::write(output, serde_json::to_vec(&results).unwrap()).unwrap();
    }
}
